function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  // Sky
  brush.fill("#e08a72", 200);
  brush.fillBleed(0.8);
  brush.beginShape(curvature);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Hills (green)
  brush.fill("#6a7e44", 150);
  brush.beginShape(curvature);
  brush.vertex(0, 50);
  brush.vertex(100, 30);
  brush.vertex(200, 10);
  brush.vertex(300, 10);
  brush.vertex(400, 50);
  brush.endShape(true);

  // Grass (soft green)
  brush.fill("#a5b98f", 120);
  brush.beginShape(curvature);
  brush.vertex(0, 60);
  brush.vertex(80, 60);
  brush.vertex(120, 70);
  brush.vertex(160, 70);
  brush.vertex(200, 80);
  brush.vertex(240, 80);
  brush.vertex(280, 90);
  brush.vertex(320, 90);
  brush.vertex(360, 100);
  brush.vertex(400, 100);
  brush.endShape(true);

  // Rocks (gray)
  brush.fill("#6b6b6b", 100);
  brush.beginShape(curvature);
  brush.vertex(0, 120);
  brush.vertex(10, 100);
  brush.vertex(20, 100);
  brush.vertex(30, 110);
  brush.vertex(40, 110);
  brush.vertex(0, 120);
  brush.endShape(true);

  // Trees (dark green with a trace of red)
  brush.fill("#2f5a32", 100);
  brush.beginShape(curvature);
  brush.vertex(0, 150);
  brush.vertex(50, 130);
  brush.vertex(100, 120);
  brush.vertex(150, 110);
  brush.vertex(200, 100);
  brush.vertex(250, 90);
  brush.vertex(300, 80);
  brush.vertex(350, 70);

