function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fill("#e08a72", 255); // orange
  brush.fill("#d8c3b6", 255); // golden
  brush.fill("#b4987d", 255); // warm pink
  brush.fill("#a1775e", 255); // deeper red

  // Hills
  brush.fill("#b3dbd0", 200); // light green
  brush.beginShape();
  vertex(0, 0);
  vertex(300, 0);
  vertex(400, 100);
  vertex(300, 250);
  vertex(0, 250);
  vertex(0, 0);
  brush.endShape(true);

  // Sky
  brush.fill("#f4efe4", 50);
  brush.beginShape();
  vertex(0, 350);
  vertex(300, 350);
  vertex(300, 200);
  vertex(0, 200);
  vertex(0, 350);
  brush.endShape(true);

  // Clouds
  brush.fill("#e6f2f8", 100);
  brush.beginShape();
  vertex(0, 380);
  vertex(100, 340);
  vertex(200, 320);
  vertex(300, 340);
  vertex(400, 380);
  vertex(300, 420);
  brush.endShape(true);

  // Sun
  brush.fill("#f9c72e", 200);
  brush.beginShape();
  vertex(200, 280);
  vertex(230, 250);
  vertex(270, 250);
  vertex(260, 280);
  brush.endShape(true);
}
