function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.stroke("#b26e42", 100); // warm orange and reds
  brush.fill("#b26e42", 100);
  brush.fill("#d9a466", 100);
  brush.fill("#d9a466", 100);
  brush.fill("#f5d9a4", 100);
  brush.fill("#f5d9a4", 100);
  brush.fill("#f5d9a4", 100);

  // hill shapes
  for (let i = 0; i < 10; i++) {
    let hills = [
      [25, 40, 30, 40, 40, 50, 60],
      [50, 55, 60, 65, 65, 70, 80],
      [40, 45, 50, 55, 55, 60, 65],
    ];
    for (let j = 0; j < hills.length; j++) {
      brush.stroke("#484b39", 100);
      brush.fill("#5a615a", 100);
      brush.fillTexture(0.7, true);
      brush.beginShape("natural");
      for (let k = 0; k < hills[j].length; k++) {
        brush.vertex(hills[j][k], hills[j][k + 1], hills[j][k + 2]);
      }
      brush.endShape(true);
    }
  }

  // clouds
  brush.stroke("#a8c8b5", 100);
  brush.fill("#a8c8b5", 100);
  for (let i = 0; i < 10; i++) {
    brush.circle(random(200), random(200), random(40, 80));
  }
}
