function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  stroke("#ffffff");
  strokeWeight(0.5);

  // Sky
  brush.fill("#a3b6c1");
  brush.fillTexture(0.2, true);
  brush.fillBleed(1);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Hills
  brush.fill("#b0c189");
  brush.fillTexture(0.5, true);
  brush.fillBleed(1);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 150);
  brush.vertex(400, 250);
  brush.vertex(0, 300);
  brush.endShape(true);

  // Grass
  brush.fill("#6b7f67");
  brush.fillTexture(0.3, true);
  brush.fillBleed(1);
  brush.beginShape();
  brush.vertex(0, 350);
  brush.vertex(400, 350);
  brush.vertex(400, 380);
  brush.vertex(0, 380);
  brush.endShape(true);

  // Horizon line
  brush.stroke("#6f7d7f");
  brush.strokeWeight(1);
  brush.line(0, 350, 400, 350);
}
