function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.fill("#e08a72", 255); // orange
  brush.fill("#ca9f8f", 255); // warm amber
  brush.fill("#cd7450", 255); // burnt red
  brush.fill("#8c5932", 255); // dark red

  // sky gradient
  brush.fill("#f4efe4", 150);
  brush.fill("#e0d0c0", 180);
  brush.fill("#c8b492", 220);
  brush.fill("#b89f85", 250);
  brush.fill("#a58c79", 255);

  // hills with light purple
  brush.fill("#d3e7f2", 255);
  brush.fill("#dfe5e5", 235);
  brush.fill("#c8d8d5", 220);

  // loop through x, y at 0 to 400
  for (let x = 0; x < width; x += 2) {
    for (let y = 0; y < height; y += 2) {
      brush.fill("#d3e7f2", 255);
      brush.fillBleed(0.5);
      brush.circle(x, y, 40);
    }
  }

  // horizons
  brush.fill("#c8d8d5", 180);
  brush.circle(200, 200, 200);
  brush.circle(200, 100, 300);
  brush.circle(200, 300, 300);
  brush.circle(300, 200, 250);
  brush.circle(100, 200, 250);
}
