  brush.fill("#90c18f", 15); // Light blue
  brush.fill("#8cb396", 15); // Sky blue
  brush.fill("#d19c8e", 15); // Gray

  brush.fillTexture(1, 10); // Straw texture

  // Trees
  brush.fill("#8b7f6f", 40); // Bush
  brush.fill("#766a4c", 40); // Sparse
  brush.fill("#90939a", 40); // Gray
  brush.beginShape(2);
  vertex(0, 0);
  vertex(40, 0);
  vertex(20, 40);
  vertex(0, 40);
  brush.endShape(true);

  // Patches
  brush.fill("#a8c4f9", 10);
  brush.fillTexture(1, 10);
  brush.fill("#d19c8e", 10);
  brush.fillTexture(1, 10);

  // Undercut
  brush.fill("#8b7f6f", 20);
  brush.fillTexture(1, 20);
  brush.fill("#766a4c", 20);
  brush.fillTexture(1, 20);
  brush.fill("#90939a", 20);

  brush.noStroke();
}
