  brush.fill("#906b4f", 200);  // Medium red at bottom
  brush.fill("#7d5b3f", 200);  // Dark red at bottom

  // Hills
  brush.fill("#85a476", 200);  // Warm green at base
  brush.fill("#709467", 180);  // Muted green
  brush.fill("#58785d", 150);  // Dark green at base
  brush.fill("#2e5d3f", 100);  // Dark green on top

  brush.beginShape();
  brush.vertex(0, 0, 100);     // Top of hill
  brush.vertex(200, 0, 100);  // Right of hill
  brush.vertex(300, 0, 100);  // Bottom of hill
  brush.vertex(300, 50, 100); // Small flat base
  brush.vertex(200, 50, 100); // Right of base
  brush.vertex(0, 50, 100);   // Left of base
  brush.endShape(true);

  // Western peak
  brush.beginShape();
  brush.vertex(0, 0, 150);    // Top
  brush.vertex(-100, 0, 150); // Left side
  brush.vertex(-50, 50, 140); // Right side
  brush.vertex(-50, 100, 130); // Flat
  brush.vertex(0, 100, 120);  // Center
  brush.endShape(true);

  // Eastern peak
  brush.beginShape();
  brush.vertex(400, 0, 150);  // Top
  brush.vertex(300, 0, 150);  // Left side
  brush.vertex(350, 50, 140); // Right side
  brush.vertex(350, 100, 130); // Flat
  brush.vertex(400, 100, 120); // Center
  brush.endShape(true);
}
